/*
 * iOS 7.0 (11A466) -> SEP 12.5.8 (16H88).
 * Numbers below are decimal unless marked 0x.
 * SKS, Mesa and generic commands have separate opcode numbers.
 *
 * SKS / keybags: iOS 7 -> SEP 12
 *   17 -> 35   read policy
 *   18 -> 36   write policy
 *   23 -> 24   credentials / lock assertions
 *   24 -> 25   lock state
 *   27 -> 28   same old payload, new opcode
 * Other supported IDs stay the same: 1,2,3,4,5,7,8,9,11,12,13,15,16.
 * Replies still go through the iOS 7 decoder for the original opcode.
 * Wrong PIN: status -8 -> -6 for action 0, so iOS 7 shows the lockout timer. (NOT EXISTS ON IOS 7.0 CHECKED ON DIFFERENT DEVICES IN COLLECTION)
 *
 * Mesa / Touch ID       old -> new        new -> old decoder
 *   sensor init          3 -> 2             2 -> 4
 *   start enrollment     7 -> 4             4 -> 8
 *   stop enrollment     17 -> 6             6 -> 18 (error -> 66)
 *   session challenge   37 -> 28           28 -> 38
 *   public key          27 -> 26           26 -> 28
 *   key exchange        29 -> 27           27 -> 26
 *   session counter     extra 72           72 -> 30
 *   finish session      39 -> 29           29 -> 40
 *   close session       41 -> 30           30 -> 42
 *   commit templates    66 -> 15           15 -> 66
 *   capture params      69 -> 7             7 -> 70
 *   process capture     10 -> 8
 *   finish match        49 -> 11           11 -> 50
 * Session counter 72 is sent after key exchange succeeds.
 * Native policy: 63 reads it (old decoder 54), 50 initializes it (decoder 66).
 * Decoder numbers are local handlers, not extra commands sent to SEP.
 *
 * Generic transport: request 57/58/59 -> 22/23/24, replies go back the other way.
 *   57: first packet, 58: upload next part, 59: download next part.
 * Commands inside those packets:
 *    1  look up a finger       2  import templates
 *    3  export templates       4  delete a finger
 *    8  calibration            9  init parameter
 *   10  sensor init           17  upload sensor image
 *   26  list fingers (0x1a)
 * Reply command = command | 0x8000: import is 0x8002, image upload is 0x8011.
 *
 * Capture: old raw 9 uploads the image with generic command 17.
 * Its upload ACK goes to old 11. Native 8 then processes the capture;
 * native 9 returns enrollment data (old 13/14), native 10 returns a match
 * (old 12). Recapture uses old 12 / status 401 to keep scanning.
 *
 * Notifications:
 *   14 -> old 64   Touch ID state for user 501
 *   62             saved finger list changed
 *   38             image channel ready (empty packet, data 0)
 * Native 14 flags, checked in order: 0x10 -> old state 5 (needs PIN),
 * 0x02 -> 3, 0x04 -> 4, 0x08 -> 1 if no bits outside 0xab; otherwise 0.
 * Check the owner and packet type before passing a reply to an old handler.
 */

#define _POSIX_C_SOURCE 200809L
#include <ctype.h>
#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <unistd.h>

struct image {
  unsigned char* data;
  unsigned char* original;
  size_t input_size, output_size;
};

static void fail(const char* message) {
  fprintf(stderr, "SEP bridge: %s\n", message);
  exit(1);
}
static void* allocate(size_t size) {
  void* p = calloc(1, size ? size : 1);
  if (!p)
    fail("out of memory");
  return p;
}
static uint32_t read32(const unsigned char* p) {
  return (uint32_t)p[0] | (uint32_t)p[1] << 8 | (uint32_t)p[2] << 16 |
         (uint32_t)p[3] << 24;
}
static uint64_t read64(const unsigned char* p) {
  return read32(p) | (uint64_t)read32(p + 4) << 32;
}
static unsigned char* read_file(const char* path, size_t* size) {
  FILE* f = fopen(path, "rb");
  struct stat st;
  if (!f || fstat(fileno(f), &st) || st.st_size < 0 ||
      st.st_size > 64 * 1024 * 1024)
    fail("cannot read component");
  *size = (size_t)st.st_size;
  unsigned char* data = allocate(*size + 1);
  if (fread(data, 1, *size, f) != *size || ferror(f))
    fail("short component read");
  fclose(f);
  return data;
}

/* Search the original bytes so earlier patches do not break later searches. */
static size_t find_code(const struct image* image, const unsigned char* pattern,
                        size_t length) {
  size_t found = SIZE_MAX;
  if (!length || length > image->input_size)
    fail("bad code signature");
  for (size_t i = 0; i <= image->input_size - length; i++) {
    if (image->original[i] != pattern[0] ||
        memcmp(image->original + i, pattern, length))
      continue;
    if (found != SIZE_MAX)
      fail("code signature is ambiguous");
    found = i;
  }
  if (found == SIZE_MAX)
    fail("driver code was not found in this kernel");
  return found;
}

/* Convert a kernel address to a file offset using the Mach-O segment map. */
static size_t kernel_offset(const struct image* image, uint64_t address,
                            size_t length) {
  if (image->input_size < 32 || read32(image->original) != 0xfeedfacf)
    fail("not an ARM64 Mach-O");
  size_t command = 32;
  for (uint32_t i = 0; i < read32(image->original + 16); i++) {
    if (command > image->input_size - 8)
      fail("bad Mach-O command");
    const unsigned char* p = image->original + command;
    uint32_t size = read32(p + 4);
    if (size < 8 || size > image->input_size - command)
      fail("bad Mach-O command size");
    if (read32(p) == 0x19 && size >= 72) {
      uint64_t start = read64(p + 24), file = read64(p + 40),
               bytes = read64(p + 48);
      if (address >= start && address - start <= bytes &&
          length <= bytes - (address - start)) {
        uint64_t offset = file + address - start;
        if (offset > image->input_size || length > image->input_size - offset)
          fail("bad kernel mapping");
        return (size_t)offset;
      }
    }
    command += size;
  }
  fail("handler destination is not mapped");
  return 0;
}
static void write_bytes(struct image* image, size_t at, const void* bytes,
                        size_t length) {
  if (at > image->output_size || length > image->output_size - at)
    fail("patch extends past component");
  memcpy(image->data + at, bytes, length);
}
static void patch_found(struct image* image, const void* signature, size_t size,
                        size_t delta, const void* replacement, size_t length) {
  size_t location = find_code(image, signature, size);
  if (delta > image->output_size - location)
    fail("bad patch displacement");
  write_bytes(image, location + delta, replacement, length);
}
static void install_handler(struct image* image, uint64_t address,
                            const void* code, size_t length) {
  size_t at = kernel_offset(image, address, length);
  for (size_t i = 0; i < length; i++)
    if (image->original[at + i])
      fail("handler space is already occupied");
  write_bytes(image, at, code, length);
}
/* Headers and trailers use file offsets. Check the old bytes before replacing them. */
static void patch_table(struct image* image, size_t at, const void* expected,
                        size_t old_length, const void* replacement,
                        size_t new_length) {
  if (old_length &&
      (at > image->input_size || old_length > image->input_size - at ||
       memcmp(image->original + at, expected, old_length)))
    fail("component table does not match 11A466");
  write_bytes(image, at, replacement, new_length);
}

