// clang-format on
/* Create a new output file; refuse to overwrite an existing one. */
static int save(const char* path, const unsigned char* data, size_t size) {
  int fd = open(path, O_WRONLY | O_CREAT | O_EXCL, 0644);
  if (fd < 0) {
    perror(path);
    return 1;
  }
  size_t done = 0;
  int failed = 0;
  while (done < size) {
    ssize_t count = write(fd, data + done, size - done);
    if (count < 0 && errno == EINTR)
      continue;
    if (count <= 0) {
      failed = 1;
      break;
    }
    done += (size_t)count;
  }
  if (fsync(fd))
    failed = 1;
  if (close(fd))
    failed = 1;
  if (failed) {
    unlink(path);
    fprintf(stderr, "Could not finish output\n");
  }
  return failed;
}

