// clang-format on
/* Write byte patches for img4. kerneldiff cannot fit all our changes. */
static int diff_files(const char* before, const char* after,
                      const char* output) {
  FILE *a = fopen(before, "rb"), *b = fopen(after, "rb");
  if (!a || !b) {
    if (a)
      fclose(a);
    if (b)
      fclose(b);
    return 1;
  }
  int fd = open(output, O_WRONLY | O_CREAT | O_EXCL, 0644);
  if (fd < 0) {
    fclose(a);
    fclose(b);
    return 1;
  }
  FILE* out = fdopen(fd, "w");
  if (!out) {
    close(fd);
    fclose(a);
    fclose(b);
    unlink(output);
    return 1;
  }
  fputs("#AMFI\n\n", out);
  size_t offset = 0;
  int x, y, failed = 0;
  for (;;) {
    x = fgetc(a);
    y = fgetc(b);
    if (x == EOF || y == EOF) {
      failed = x != y;
      break;
    }
    if (x != y)
      fprintf(out, "0x%zx 0x%x 0x%x\n", offset,
              x < 128 ? x : (unsigned)x | 0xffffff00u,
              y < 128 ? y : (unsigned)y | 0xffffff00u);
    offset++;
  }
  if (ferror(a) || ferror(b) || ferror(out))
    failed = 1;
  fclose(a);
  fclose(b);
  if (fclose(out))
    failed = 1;
  if (failed)
    unlink(output);
  return failed;
}

static int apply_profile(const char* name, const char* input,
                         const char* output) {
  struct image image = {0};
  image.original = read_file(input, &image.input_size);

  if (!strcmp(name, "kernel")) {
    if (image.input_size != 17117184)
      fail("wrong kernel size for 11A466");
    image.output_size = 17117184;
  }

  else if (!strcmp(name, "restore-kernel")) {
    if (image.input_size != 17117184)
      fail("wrong restore-kernel size for 11A466");
    image.output_size = 17117184;
  }

  else if (!strcmp(name, "asr")) {
    if (image.input_size != 239424)
      fail("wrong asr size for 11A466");
    image.output_size = 239424;
  }

  else if (!strcmp(name, "powerd")) {
    if (image.input_size != 142384)
      fail("wrong powerd size for 11A466");
    image.output_size = 143808;
  }

  else
    fail("unknown patch profile");
  image.data = allocate(image.output_size);
  memcpy(image.data, image.original,
         image.input_size < image.output_size ? image.input_size
                                              : image.output_size);
  const char* shown = getenv("SEP_BRIDGE_BANNER_SHOWN");
  if (!shown || strcmp(shown, "1"))
    fputs(banner, stdout);

  if (!strcmp(name, "kernel")) {

    patch_mesa_enrollment(&image);

    patch_mesa_policy(&image);

    patch_mesa_calibration(&image);

    patch_mesa_capture(&image);

    patch_kernel_compatibility(&image);

    patch_sep_rpc_gates(&image);

    patch_mesa_results(&image);

    patch_mesa_identities(&image);

    patch_pin_backoff(&image);

    patch_sep_keybag_storage(&image);

    patch_mesa_storage(&image);

    patch_sep_keybag_codec(&image);

    patch_sep_channels(&image);

    patch_mesa_hooks(&image);

    patch_sep_keybag_hooks(&image);

    patch_sep_keybag_messages(&image);

  }

  else if (!strcmp(name, "restore-kernel")) {

    patch_restore_kernel_compatibility(&image);

    patch_restore_sep_channels(&image);

    patch_restore_mesa_hooks(&image);

    patch_restore_sep_keybag_hooks(&image);

    patch_restore_sep_keybag_messages(&image);

  }

  else if (!strcmp(name, "asr")) {

    patch_asr(&image);

  }

  else if (!strcmp(name, "powerd")) {

    patch_powerd(&image);
  }

  int result = save(output, image.data, image.output_size);
  free(image.data);
  free(image.original);
  if (!result)
    printf("Patched %s\n", name);
  return result;
}

/* Small plist reader for finding and replacing BuildManifest entries. */
struct plist_node {
  char *tag, *text;
  struct plist_node *child, *next;
};
static char* copy_text(const char* start, size_t size) {
  char* text = allocate(size + 1);
  memcpy(text, start, size);
  return text;
}
static struct plist_node* node(const char* tag, const char* text) {
  struct plist_node* n = allocate(sizeof(*n));
  n->tag = strdup(tag);
  n->text = strdup(text ? text : "");
  if (!n->tag || !n->text)
    fail("out of memory");
  return n;
}
static void skip_xml_space(char** cursor) {
  for (;;) {
    while (isspace((unsigned char)**cursor))
      (*cursor)++;
    if (!strncmp(*cursor, "<!--", 4)) {
      char* end = strstr(*cursor + 4, "-->");
      if (!end)
        fail("unfinished XML comment");
      *cursor = end + 3;
    } else if (!strncmp(*cursor, "<?", 2) || !strncmp(*cursor, "<!", 2)) {
      char* end = strchr(*cursor, '>');
      if (!end)
        fail("unfinished XML header");
      *cursor = end + 1;
    } else
      break;
  }
}
static struct plist_node* parse_xml_node(char** cursor, unsigned depth) {
  if (depth > 64)
    fail("plist nesting is too deep");
  skip_xml_space(cursor);
  if (**cursor != '<' || (*cursor)[1] == '/')
    fail("expected a plist element");
  char* start = ++*cursor;
  while (isalnum((unsigned char)**cursor))
    (*cursor)++;
  if (*cursor == start)
    fail("bad plist tag");
  char* tag = copy_text(start, (size_t)(*cursor - start));
  struct plist_node* n = node(tag, "");
  free(tag);
  char* end = strchr(*cursor, '>');
  if (!end)
    fail("unfinished plist tag");
  int empty = end > *cursor && end[-1] == '/';
  *cursor = end + 1;
  if (empty)
    return n;
  if (!strcmp(n->tag, "dict") || !strcmp(n->tag, "array") ||
      !strcmp(n->tag, "plist")) {
    struct plist_node** tail = &n->child;
    for (;;) {
      skip_xml_space(cursor);
      if (!strncmp(*cursor, "</", 2))
        break;
      *tail = parse_xml_node(cursor, depth + 1);
      tail = &(*tail)->next;
    }
  } else {
    end = strchr(*cursor, '<');
    if (!end)
      fail("unfinished plist value");
    free(n->text);
    n->text = copy_text(*cursor, (size_t)(end - *cursor));
    *cursor = end;
  }
  size_t length = strlen(n->tag);
  if (strncmp(*cursor, "</", 2) || strncmp(*cursor + 2, n->tag, length) ||
      (*cursor)[length + 2] != '>')
    fail("mismatched plist closing tag");
  *cursor += length + 3;
  return n;
}
static struct plist_node* load_plist(const char* path) {
  size_t size;
  unsigned char* data = read_file(path, &size);
  char* cursor = (char*)data;
  struct plist_node* root = parse_xml_node(&cursor, 0);
  free(data);
  if (strcmp(root->tag, "plist") || !root->child ||
      strcmp(root->child->tag, "dict"))
    fail("expected an XML plist dictionary");
  return root->child;
}
static struct plist_node* dict_get(struct plist_node* dict, const char* key) {
  if (!dict || strcmp(dict->tag, "dict"))
    fail("expected a plist dictionary");
  for (struct plist_node* n = dict->child; n; n = n->next->next) {
    if (strcmp(n->tag, "key") || !n->next)
      fail("bad plist dictionary entry");
    if (!strcmp(n->text, key))
      return n->next;
  }
  return NULL;
}
static struct plist_node* required(struct plist_node* dict, const char* key) {
  struct plist_node* n = dict_get(dict, key);
  if (!n)
    fail(key);
  return n;
}
static const char* string_value(struct plist_node* dict, const char* key) {
  struct plist_node* n = required(dict, key);
  if (strcmp(n->tag, "string"))
    fail("expected a plist string");
  return n->text;
}
static struct plist_node* clone_node(const struct plist_node* source) {
  struct plist_node* copy = node(source->tag, source->text);
  struct plist_node** tail = &copy->child;
  for (const struct plist_node* c = source->child; c; c = c->next) {
    *tail = clone_node(c);
    tail = &(*tail)->next;
  }
  return copy;
}
static void free_node(struct plist_node* n) {
  while (n) {
    struct plist_node* next = n->next;
    free_node(n->child);
    free(n->tag);
    free(n->text);
    free(n);
    n = next;
  }
}
static void dict_set(struct plist_node* dict, const char* key,
                     struct plist_node* value) {
  for (struct plist_node* n = dict->child; n; n = n->next->next) {
    if (!n->next)
      fail("bad plist dictionary");
    if (!strcmp(n->text, key)) {
      struct plist_node* old = n->next;
      value->next = old->next;
      old->next = NULL;
      n->next = value;
      free_node(old);
      return;
    }
  }
  struct plist_node** tail = &dict->child;
  while (*tail)
    tail = &(*tail)->next;
  *tail = node("key", key);
  (*tail)->next = value;
}
static void write_xml_node(FILE* f, const struct plist_node* n,
                           unsigned depth) {
  for (; n; n = n->next) {
    fprintf(f, "%*s<%s", (int)(depth * 2), "", n->tag);
    if (!strcmp(n->tag, "true") || !strcmp(n->tag, "false")) {
      fputs("/>\n", f);
    } else if (n->child || !strcmp(n->tag, "dict") ||
               !strcmp(n->tag, "array")) {
      fputs(">\n", f);
      write_xml_node(f, n->child, depth + 1);
      fprintf(f, "%*s</%s>\n", (int)(depth * 2), "", n->tag);
    } else {
      /* Keep existing XML escapes when writing the plist back. */
      fprintf(f, ">%s</%s>\n", n->text, n->tag);
    }
  }
}
static void write_plist(const char* path, struct plist_node* dict) {
  FILE* f = fopen(path, "wb");
  if (!f)
    fail("cannot write plist");
  fputs("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
        "<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" "
        "\"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n"
        "<plist version=\"1.0\">\n",
        f);
  write_xml_node(f, dict, 1);
  fputs("</plist>\n", f);
  if (ferror(f) || fclose(f))
    fail("could not finish plist");
}
static char* join_path(const char* directory, const char* member) {
  size_t size = strlen(directory) + strlen(member) + 2;
  char* result = allocate(size);
  snprintf(result, size, "%s/%s", directory, member);
  return result;
}
static struct plist_node* erase_identity(struct plist_node* manifest) {
  struct plist_node* identities = required(manifest, "BuildIdentities");
  for (struct plist_node* i = identities->child; i; i = i->next) {
    struct plist_node* info = required(i, "Info");
    if (!strcmp(string_value(info, "DeviceClass"), "n51ap") &&
        !strcmp(string_value(info, "RestoreBehavior"), "Erase"))
      return i;
  }
  fail("n51ap erase identity was not found");
  return NULL;
}
static const char* component_path(struct plist_node* entries,
                                  const char* name) {
  return string_value(required(required(entries, name), "Info"), "Path");
}
static const char* nor_names[] = {"LLB",
                                  "iBoot",
                                  "AppleLogo",
                                  "RecoveryMode",
                                  "BatteryCharging0",
                                  "BatteryCharging1",
                                  "BatteryFull",
                                  "BatteryLow0",
                                  "BatteryLow1",
                                  "BatteryPlugin"};

/* Give the shell component names and paths from the selected manifest. */
static int list_components(const char* kind, const char* path) {
  struct plist_node* m = load_plist(path);
  const char* build = string_value(m, "ProductBuildVersion");
  struct plist_node* entries = required(erase_identity(m), "Manifest");
  if (!strcmp(kind, "base")) {
    if (strcmp(build, "16H88"))
      fail("base must be 12.5.8 / 16H88");
    for (size_t i = 0; i < sizeof(nor_names) / sizeof(nor_names[0]); i++)
      printf("%s|%s\n", nor_names[i], component_path(entries, nor_names[i]));
    printf("SEP|%s\n", component_path(entries, "SEP"));
  } else if (!strcmp(kind, "target")) {
    if (strcmp(build, "11A466") ||
        strcmp(string_value(m, "ProductVersion"), "7.0"))
      fail("target must be iPhone6,1 iOS 7.0 / 11A466");
    const char* names[] = {"KernelCache", "RestoreRamDisk", "OS",
                           "iBSS", "iBEC", "DeviceTree",
                           "AppleLogo", "iBoot"};
    for (size_t i = 0; i < sizeof(names) / sizeof(names[0]); i++)
      printf("%s|%s\n", names[i], component_path(entries, names[i]));
  } else
    fail("unknown component inventory");
  return 0;
}

/* BuildManifest needs a SHA-1 digest for each changed component. */
static struct plist_node* component_digest(const char* path) {
  int descriptors[2], status;
  if (pipe(descriptors))
    fail("cannot open digest pipe");
  pid_t child = fork();
  if (child < 0)
    fail("cannot start openssl");
  if (!child) {
    close(descriptors[0]);
    if (dup2(descriptors[1], STDOUT_FILENO) < 0)
      _exit(126);
    close(descriptors[1]);
    execlp("openssl", "openssl", "dgst", "-sha1", "-binary", path,
           (char*)NULL);
    _exit(127);
  }
  close(descriptors[1]);
  unsigned char bytes[21];
  size_t count = 0;
  while (count < sizeof(bytes)) {
    ssize_t n = read(descriptors[0], bytes + count, sizeof(bytes) - count);
    if (n < 0 && errno == EINTR)
      continue;
    if (n < 0)
      fail("cannot read digest");
    if (!n)
      break;
    count += (size_t)n;
  }
  close(descriptors[0]);
  while (waitpid(child, &status, 0) < 0)
    if (errno != EINTR)
      fail("cannot wait for openssl");
  if (count != 20 || !WIFEXITED(status) || WEXITSTATUS(status))
    fail("cannot fill component Digest");
  static const char alphabet[] =
      "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  char encoded[29];
  size_t out = 0;
  for (size_t i = 0; i < count; i += 3) {
    uint32_t n = (uint32_t)bytes[i] << 16;
    if (i + 1 < count)
      n |= (uint32_t)bytes[i + 1] << 8;
    if (i + 2 < count)
      n |= bytes[i + 2];
    encoded[out++] = alphabet[n >> 18];
    encoded[out++] = alphabet[(n >> 12) & 63];
    encoded[out++] = i + 1 < count ? alphabet[(n >> 6) & 63] : '=';
    encoded[out++] = i + 2 < count ? alphabet[n & 63] : '=';
  }
  encoded[out] = 0;
  return node("data", encoded);
}
static void copy_component_file(const char* source, const char* destination) {
  size_t size;
  unsigned char* data = read_file(source, &size);
  FILE* f = fopen(destination, "wb");
  if (!f || fwrite(data, 1, size, f) != size)
    fail("cannot copy NOR component");
  free(data);
  if (fclose(f))
    fail("cannot finish NOR component");
}
static int prepare_manifest(const char* target_directory,
                            const char* base_directory) {
  char* target_path = join_path(target_directory, "BuildManifest.plist");
  struct plist_node* target = load_plist(target_path);
  struct plist_node* base =
      load_plist(join_path(base_directory, "BuildManifest.plist"));
  if (strcmp(string_value(target, "ProductBuildVersion"), "11A466") ||
      strcmp(string_value(base, "ProductBuildVersion"), "16H88"))
    fail("wrong target or base build");
  struct plist_node* native = required(erase_identity(base), "Manifest");
  struct plist_node* identities = required(target, "BuildIdentities");
  for (struct plist_node* i = identities->child; i; i = i->next) {
    struct plist_node* entries = required(i, "Manifest");
    char* flash_manifest =
        join_path(target_directory, component_path(entries, "LLB"));
    char* slash = strrchr(flash_manifest, '/');
    if (!slash)
      fail("bad LLB path");
    strcpy(slash + 1, "manifest");
    if (unlink(flash_manifest) && errno != ENOENT)
      fail("cannot remove old NOR inventory");
    free(flash_manifest);
    /* With all_flash/manifest removed, futurerestore uses these flags for NOR. */
    for (struct plist_node* key = entries->child; key; key = key->next->next) {
      struct plist_node* info = required(key->next, "Info");
      dict_set(info, "IsFirmwarePayload", node("false", ""));
      dict_set(info, "IsSecondaryFirmwarePayload", node("false", ""));
    }
    for (size_t index = 0; index < sizeof(nor_names) / sizeof(nor_names[0]);
         index++) {
      const char* name = nor_names[index];
      char* member = strdup(component_path(entries, name));
      struct plist_node* replacement = clone_node(required(native, name));
      struct plist_node* info = required(replacement, "Info");
      dict_set(info, "Path", node("string", member));
      dict_set(info, "IsFirmwarePayload", node("true", ""));
      dict_set(entries, name, replacement);
      char filename[64];
      snprintf(filename, sizeof(filename), "%s.im4p", name);
      copy_component_file(join_path(base_directory, filename),
                          join_path(target_directory, member));
      free(member);
    }
    const char* sep_names[] = {"SEP", "RestoreSEP"};
    for (unsigned n = 0; n < 2; n++) {
      char* member = strdup(component_path(entries, sep_names[n]));
      struct plist_node* replacement =
          clone_node(required(native, sep_names[n]));
      dict_set(required(replacement, "Info"), "Path", node("string", member));
      dict_set(entries, sep_names[n], replacement);
      copy_component_file(join_path(base_directory, "SEP.im4p"),
                          join_path(target_directory, member));
      free(member);
    }
    dict_set(required(required(entries, "RestoreKernelCache"), "Info"), "Path",
             node("string", "Firmware/sep-bridge/restore-kernel.im4p"));
    struct plist_node *stage = node("dict", ""), *info = node("dict", "");
    dict_set(stage, "Trusted", node("true", ""));
    dict_set(info, "Path",
             node("string", "Firmware/sep-bridge/iBoot.rlgo.im4p"));
    dict_set(info, "IsFirmwarePayload", node("true", ""));
    dict_set(stage, "Info", info);
    /*
     * Keep the name TetheredBootStage. An iBoot* name makes futurerestore put
     * this stage first; the signed 12.x iBoot must go first instead.
     */
    dict_set(entries, "TetheredBootStage", stage);
    dict_set(required(required(entries, "DeviceTree"), "Info"),
             "IsFirmwarePayload", node("true", ""));
    const char* changed[] = {"KernelCache", "RestoreKernelCache",
                             "RestoreRamDisk", "DeviceTree",
                             "TetheredBootStage"};
    for (size_t n = 0; n < sizeof(changed) / sizeof(changed[0]); n++) {
      struct plist_node* entry = required(entries, changed[n]);
      dict_set(entry, "Digest",
               component_digest(join_path(
                   target_directory, component_path(entries, changed[n]))));
    }
  }
  write_plist(target_path, target);
  return 0;
}

static int write_restore_options(const char* path) {
  struct plist_node *options = node("dict", ""), *padding = node("dict", "");
  dict_set(options, "MinimumSystemPartition", node("integer", "2682"));
  dict_set(options, "SystemPartitionSize", node("integer", "4200"));
  dict_set(options, "UpdateBaseband", node("true", ""));
  const unsigned sizes[] = {8, 16, 32, 64, 128, 256, 512, 768, 1024};
  const unsigned extra[] = {180, 260, 320, 640, 1280, 1280, 1280, 1280, 1280};
  for (size_t i = 0; i < sizeof(sizes) / sizeof(sizes[0]); i++) {
    char key[16], value[16];
    snprintf(key, sizeof(key), "%u", sizes[i]);
    snprintf(value, sizeof(value), "%u", extra[i]);
    dict_set(padding, key, node("integer", value));
  }
  dict_set(options, "SystemPartitionPadding", padding);
  write_plist(path, options);
  return 0;
}

int main(int argc, char** argv) {
  if (argc == 2 && !strcmp(argv[1], "--version")) {
    puts("v0.0.1-beta1");
    return 0;
  }
  if (argc == 2 && !strcmp(argv[1], "--banner")) {
    fputs(banner, stdout);
    return 0;
  }
  if (argc == 2 && !strcmp(argv[1], "--profiles")) {
    puts("kernel\nrestore-kernel\nasr\npowerd");
    return 0;
  }
  if (argc == 3 && !strcmp(argv[1], "--extract-powerd-guard"))
    return write_powerd_sleep_guard(argv[2]);
  if (argc == 3 && !strcmp(argv[1], "restore-options"))
    return write_restore_options(argv[2]);
  if (argc == 4 && !strcmp(argv[1], "components"))
    return list_components(argv[2], argv[3]);
  if (argc == 4 && !strcmp(argv[1], "prepare-manifest"))
    return prepare_manifest(argv[2], argv[3]);
  if (argc == 5 && !strcmp(argv[1], "patch"))
    return apply_profile(argv[2], argv[3], argv[4]);
  if (argc == 5 && !strcmp(argv[1], "diff"))
    return diff_files(argv[2], argv[3], argv[4]);
  fprintf(stderr,
          "Usage: %s patch {kernel|restore-kernel|asr|powerd} INPUT "
          "OUTPUT\n"
          "       %s diff STOCK PATCHED OUTPUT\n"
          "       %s components {base|target} BuildManifest.plist\n"
          "       %s prepare-manifest TARGET_DIRECTORY BASE_DIRECTORY\n"
          "       %s restore-options OUTPUT\n"
          "       %s --extract-powerd-guard OUTPUT\n",
          argv[0], argv[0], argv[0], argv[0], argv[0], argv[0]);
  return 2;
}
